JS=JS[:JS.index("let box=document.querySelector('[data-wo-calc]')")]+'''let box=document.querySelector('[data-wo-calc]');if(!box)return;const cfg=JSON.parse(document.getElementById('wo-config').textContent),input=box.querySelector('input'),link=box.querySelector('[data-request]');function update(){const n=Number(input.value),ok=Number.isInteger(n)&&n>=1&&n<=40;input.setCustomValidity(ok?'':cfg.valid);if(!ok){link.removeAttribute('href');link.setAttribute('aria-disabled','true');return}link.removeAttribute('aria-disabled');const fmt=new Intl.NumberFormat(cfg.lang,{maximumFractionDigits:2}),total=n*(cfg.price-cfg.guide)+cfg.guide,each=total/n;document.querySelectorAll('[data-each]').forEach(el=>el.textContent=fmt.format(each));const share=box.querySelector('[data-guide-share]');if(share)share.textContent=fmt.format(cfg.guide/n)+' MAD';box.querySelector('[data-total]').textContent=fmt.format(total)+' MAD';link.href='https://wa.me/212667772551?text='+encodeURIComponent(cfg.msg+' «'+cfg.name+'» — '+n+' '+cfg.people+' — '+fmt.format(each)+' MAD / '+cfg.each+' — '+fmt.format(total)+' MAD / '+cfg.total)}input.addEventListener('input',update);update()})();'''


GUIDE_NOTES={
 'fr':dict(base='Pour 1 personne',group='pour tout le groupe',note='Le guide coûte 500 MAD pour tout le groupe, à partager entre les participants. Les autres services sont facturés par personne. Modifiez le nombre de personnes pour voir votre prix.',share='Votre part du guide',basis='Prix par personne · guide à 500 MAD partagé entre les participants'),
 'en':dict(base='For 1 guest',group='for the whole group',note='The guide costs 500 MAD for the whole group, shared between participants. Other services are priced per person. Change the number of guests to see your price.',share='Your share of the guide',basis='Per-person prices · 500 MAD guide fee shared between guests'),
 'es':dict(base='Para 1 persona',group='para todo el grupo',note='El guía cuesta 500 MAD para todo el grupo, repartidos entre los participantes. Los demás servicios se cobran por persona. Cambia el número de personas para ver tu precio.',share='Tu parte del guía',basis='Precios por persona · guía de 500 MAD compartido entre participantes'),
 'ar':dict(base='عند الحجز لشخص واحد',group='للمجموعة كاملة',note='ثمن المرشد 500 درهم للمجموعة كاملة، يتقسم على عدد المشاركين. باقي الخدمات محسوبة للشخص الواحد. غيّر عدد الأشخاص باش تعرف الثمن ديالك.',share='نصيبك من ثمن المرشد',basis='أثمنة للشخص · ثمن المرشد 500 درهم يتقسم على المجموعة')
}
def guide_fee(i):return 500 if i in (0,1,4) else 0
def price_note(l,i):return GUIDE_NOTES[l]['base'] if guide_fee(i) else D[l]['each']

def esc(s):return html.escape(str(s),quote=True)
def picture(src,alt,cls='',eager=False):
 return f'<img class="{cls}" src="{BASE}images/{src}" alt="{esc(alt)}" width="800" height="600" loading="{"eager" if eager else "lazy"}" decoding="async">'
def card(l,i):
 d=D[l];c=CONTENT[l]
 short={'fr':['Nos escapades','Sur réservation','Découvrir'],'en':['Our escapes','On request','Explore'],'es':['Nuestras escapadas','Bajo reserva','Descubrir'],'ar':['عروض الويكاند','بالحجز المسبق','اكتشف']}[l]
 return f'''<a class="wo-card" href="{BASE}{l}/{SLUGS[i]}/" aria-label="{esc(c['names'][i])} — {d['view']}">{picture(IMAGES[i],'')}<span class="wo-card-badge">{short[1]}</span><div class="wo-card-copy"><span class="wo-card-tag">{c['tags'][i]}</span><h3>{c['names'][i]}</h3><div class="wo-card-duration">◷ {c['duration'][i]}</div><div class="wo-card-bottom"><div class="wo-card-price"><strong>{PRICES[i]:,} MAD</strong><small>{price_note(l,i)}</small></div><span class="wo-card-cta">{short[2]} ↗</span></div></div></a>'''.replace(',000',' 000').replace(',400',' 400').replace(',500',' 500')
STORY={
'fr':[
 'Prendre de la hauteur, puis retrouver le calme du camp : ce séjour vous invite à découvrir deux visages d’Imsfrane. Le samedi est consacré au sommet et à ses panoramas ; le dimanche, le chemin vous rapproche de l’eau, des gorges et des cascades. Entre les deux, les nuits sous la tente prolongent le temps passé dehors, au rythme de la montagne.',
 'Un même paysage, plusieurs façons de le découvrir. Les pistes se parcourent d’abord en quad et à vélo, avant de laisser place aux sentiers de randonnée. Ce séjour associe le plaisir de rouler, l’effort de la montée et la découverte des gorges. Les activités sont réparties sur trois jours pour garder des moments de pause et profiter des deux nuits au camp.',
 'Sur deux jours, la rivière devient le fil du voyage. Les paysages se découvrent depuis le raft, au gré des passages d’eau vive et des portions plus calmes. Cette formule laisse davantage de place à l’expérience du parcours : apprendre à pagayer ensemble, observer les reliefs et avancer avec l’équipe. Les étapes précises sont préparées selon les conditions de l’Ahansal.',
 'Retrouver une maison après une descente sur l’Ahansal : une façon simple de mêler aventure et temps de repos. Vous vous installez à Tilouguite pour deux nuits et consacrez une journée au rafting de 12 km. Le reste du séjour garde un rythme libre, pour profiter des alentours sans enchaîner les activités.',
 'Depuis les hauteurs de Msfrane jusqu’au courant de l’Ahansal, ce programme fait dialoguer la montagne et la rivière. Une journée de randonnée rassemble le sommet, les gorges et les cascades ; une autre vous emmène sur l’eau pour 12 km de rafting. Les deux nuits en maison offrent un point de retour pour se reposer entre ces journées actives.'
],
'en':[
 'Climb into the mountains, then return to the quiet of camp. This stay brings together two sides of Imsfrane: summit views on Saturday, followed by gorges and waterfalls on Sunday. Two nights in a tent extend your time outdoors, with space between the walks to rest and enjoy the setting.',
 'One landscape, several ways to explore it. Start on the tracks by quad and mountain bike, then follow the walking trails towards the summit and the gorges. Spread over three days, the activities combine riding, hiking and time at camp, with breaks between outings and two nights close to nature.',
 'For two days, the river leads the journey. From the raft, lively stretches give way to calmer moments and changing views of the valley. There is time to learn to paddle together, watch the landscape and follow the route with the team. The exact stages are planned around conditions on the Ahansal.',
 'Return to a house after a day on the Ahansal: a simple balance of adventure and rest. Stay in Tilouguite for two nights, with one day devoted to a 12 km rafting trip. The rest of the visit remains unhurried, leaving time to enjoy the surroundings without a packed activity schedule.',
 'From the heights of Msfrane to the current of the Ahansal, this stay combines mountain trails with time on the river. A full hiking day takes in the summit, gorges and waterfalls; another day brings 12 km of rafting. Two nights in a house provide a place to rest between the active days.'
],
'es':[
 'Subir a la montaña y regresar a la calma del campamento: una estancia para descubrir dos caras de Imsfrane. El sábado se dedica a la cumbre y sus vistas; el domingo, a las gargantas y cascadas. Las dos noches en tienda prolongan el tiempo al aire libre y permiten descansar entre las rutas.',
 'Un paisaje y varias maneras de descubrirlo. Primero, las pistas en quad y bicicleta; después, los senderos hacia la cumbre y las gargantas. Las actividades se reparten en tres días para combinar conducción, senderismo y momentos de descanso, con dos noches en el campamento.',
 'Durante dos días, el río marca el camino. Desde la balsa, los tramos animados alternan con momentos más tranquilos y nuevas vistas del valle. La experiencia permite remar en equipo, observar el paisaje y avanzar con los acompañantes. Las etapas se preparan según las condiciones del Ahansal.',
 'Volver a una casa después de descender el Ahansal: una forma sencilla de combinar aventura y descanso. Dos noches en Tilouguite y una jornada dedicada al rafting de 12 km. El resto de la estancia queda libre para disfrutar de los alrededores sin encadenar actividades.',
 'Desde las alturas de Msfrane hasta la corriente del Ahansal, este programa une montaña y río. Una jornada de senderismo reúne cumbre, gargantas y cascadas; otra propone 12 km de rafting. Las dos noches en casa ofrecen un lugar para descansar entre estas jornadas activas.'
],
'ar':[
 'بين إطلالة القمة وهدوء المخيم، يأخذك هذا البرنامج لاكتشاف وجهين من مسفران. يوم السبت للمشي نحو المرتفعات والاستمتاع بمناظر الجبال، ويوم الأحد للاقتراب من مياه أحنصال ومضايقه وشلالاته. وبين الجولتين، تمنحك ليلتان في الخيمة وقتاً أطول وسط الطبيعة، مع فرصة للراحة والاستمتاع بأجواء المكان.',
 'نفس المنطقة، وتجارب مختلفة لاكتشافها: تبدأ على المسالك بالكواد والدراجة، ثم تواصل سيراً نحو القمة والمضايق. يجمع البرنامج متعة القيادة والمشي الجبلي في ثلاثة أيام، مع توزيع الأنشطة وترك فترات للاستراحة. وفي المساء، تعود إلى المخيم لقضاء ليلتي الجمعة والسبت وسط الطبيعة.',
 'في هذا البرنامج، يصبح النهر هو طريق الرحلة على مدى يومين. تتبدل المناظر من داخل الرافت، بين مقاطع حركية وأخرى أهدأ تتيح مشاهدة الوادي. تجربة فيها وقت للتجديف مع الفريق والتعرف على إيقاع النهر، بينما تتحدد المراحل الدقيقة حسب ظروف أحنصال ومستوى مياهه.',
 'يوم من المغامرة على مياه أحنصال، ثم العودة إلى منزل للراحة: إقامة تجمع النشاط والهدوء بلا برنامج مزدحم. تستقر في تليوكت لليلتين، وتخصص يوماً لرافتينغ 12 كلم. أما بقية الوقت، فتبقى حرة للاستمتاع بالمحيط والراحة قبل المغادرة.',
 'من مرتفعات مسفران إلى مياه أحنصال، يجمع هذا البرنامج تجربة الجبل وتجربة النهر. يوم مشي كامل للقمة والمضايق والشلالات، ويوم آخر للرافتينغ على مسافة 12 كلم. وبين اليومين، تكون الإقامة في منزل لليلتين فرصة للراحة والاستعداد للمرحلة التالية.'
]}

