def detail(l,i):
 d=D[l];c=CONTENT[l]
 hero_images=[IMAGES[i], 'rando-IMG_6269.webp' if i<2 or i==4 else 'blog-oued-ahansal-800.webp', 'vtt-800.webp' if i==1 else ('rando-IMG_7453.webp' if i==0 else ('raft3.webp' if i==3 else 'raft2-800.webp'))]
 hero=f'''<header class="wo-editorial-head"><span class="wo-tag">{c['tags'][i]}</span><h1>{c['names'][i]}</h1><p>{c['descs'][i]}</p></header><div class="wo-mosaic">{''.join(picture(src,c['photo'],eager=(n==0)) for n,src in enumerate(hero_images))}</div><div class="wo-summary"><div class="wo-summary-meta"><span>◷ {c['duration'][i]}</span><div class="wo-price"><span data-each>{PRICES[i]}</span> <small>{d['unit']}</small></div></div><a href="#offer-price">{c['price']} ↗</a></div>'''

 days=[]
 for n,j in enumerate(SEQUENCES[i]):
  label=c['two'][n] if i==2 else c['days'][n]
  title=c['labels'][j] if j>=0 else c['labels'][0]
  text=c['texts'][j] if j>=0 else c['house']
  src=DAY_IMAGES[j] if j>=0 else 'blog-oued-ahansal-800.webp'
  # The house step shows the surrounding river, not an unverified house interior.
  alt=title if j>=0 else c['photo']
  sentences=re.split(r'(?<=[.!؟])\s+',text);mid=max(1,len(sentences)//2)
  paragraphs=''.join('<p>'+part+'</p>' for part in (' '.join(sentences[:mid]),' '.join(sentences[mid:])) if part)
  days.append(f'<section class="wo-day" id="day-{n+1}"><div class="wo-day-heading"><span class="wo-day-number" aria-hidden="true">{n+1:02}</span><div><span class="wo-day-label">{label}</span><h3>{title}</h3></div></div><figure>{picture(src,alt)}<figcaption>{alt}</figcaption></figure><div class="wo-day-body">{paragraphs}</div></section>')
 gallery=''
 if i==1:
  gallery='<div class="wo-gallery">'+''.join(f'<figure>{picture(src,c["items"][k])}<figcaption>{c["items"][k]}</figcaption></figure>' for src,k in [('quad-new/IMG_0310.webp',2),('vtt-800.webp',3)])+'</div>'
 option=f'<p class="wo-option">{c["option"]}</p>' if i<2 else ''
 season=f'<p class="wo-notes">{d["season"]}</p>' if i>=2 else ''
 rows=''.join(f'<div class="wo-line"><span>{c["items"][k]}<br><small>{GUIDE_NOTES[l]["group"] if k==1 else d["each"]}</small></span><b>{v} MAD</b></div>' for k,v in PARTS[i])
 guideinfo=(f'<p class="wo-option">{GUIDE_NOTES[l]["note"]}</p><div class="wo-line"><span>{GUIDE_NOTES[l]["share"]}</span><b data-guide-share>500 MAD</b></div>' if guide_fee(i) else '')
 aside=f'''<aside class="wo-box" id="offer-price" data-wo-calc><h2>{c['price']}</h2><p class="wo-fine">{d['each']}</p>{rows}<div class="wo-line wo-total"><span>{d['each']}</span><b><span data-each>{PRICES[i]}</span> MAD</b></div>{option}<div class="wo-fields"><label>{d['people']}<input type="number" min="1" max="40" step="1" value="1" required></label></div>{guideinfo}<div class="wo-line"><span>{d['total']}</span><b data-total>{PRICES[i]} MAD</b></div><a class="wo-btn" data-request href="https://wa.me/212667772551">{d['request']} ↗</a><p class="wo-fine">{c['requestNote']}</p><p class="wo-fine">{d['weather']}</p></aside>'''
 nav='<nav class="wo-day-nav" aria-label="'+d['program']+'">'+''.join(f'<a href="#day-{n+1}">{label}</a>' for n,label in enumerate(c['two'] if i==2 else c['days']))+'</nav>'
 return f'''<main id="mainContent" class="wo wo-page"><a class="wo-back" href="{BASE}{l}/#weekend-offers">← {d['back']}</a>{hero}<div class="wo-grid"><article class="wo-reading"><p class="wo-story-lead">{STORY[l][i]}</p><h2>{d['program']}</h2>{nav}{''.join(days)}{gallery}<section class="wo-info-panel"><h2>{d['included']}</h2><p class="wo-notes">{c['notes'][i]}</p>{season}</section><div class="wo-prep"><h2>{c['prepareTitle']}</h2><p class="wo-notes">{c['prepare']}</p></div></article>{aside}</div></main>'''
def build(root=ROOT):
 (root/'weekend-offers.css').write_text(CSS);(root/'weekend-offers.js').write_text(JS)
 for l,d in D.items():
  c=CONTENT[l];home=root/l/'index.html';source=home.read_text()
  # Idempotent for local rebuilds and older demo mirrors.
  source=re.sub(r'<section class="wo" id="weekend-offers".*?</section>','',source,flags=re.S)
  source=re.sub(r'<link[^>]*href="[^"]*weekend-offers.css[^"]*"[^>]*>|<script[^>]*src="[^"]*weekend-offers.js[^"]*"[^>]*></script>','',source)
  assets=f'<link rel="stylesheet" href="{BASE}weekend-offers.css?v=editorial7b"><script defer src="{BASE}weekend-offers.js?v=editorial7b"></script>'
  title={'fr':'Nos escapades','en':'Our escapes','es':'Nuestras escapadas','ar':'عروض الويكاند'}[l]
  carousel=f'''<section class="wo" id="weekend-offers" data-wo-carousel aria-label="{title}"><div class="wo-heading"><div><p class="wo-kicker">{d['kicker']}</p><h2>{title}</h2><p class="wo-intro">{c['intro']}</p></div><div class="wo-controls"><button type="button" data-wo-prev aria-label="{d['prev']}">{'→' if l=='ar' else '←'}</button><button type="button" data-wo-pause data-play="{d['play']}" data-pause="{d['pause']}">{d['pause']}</button><button type="button" data-wo-next aria-label="{d['next']}">{'←' if l=='ar' else '→'}</button></div></div><div class="wo-track">{''.join(card(l,i) for i in range(5))}</div><p class="wo-card-basis">{GUIDE_NOTES[l]['basis']}</p></section>'''
  match=re.search(r'<section\b[^>]*\bid="activities"',source);assert match,l
  home.write_text((source[:match.start()]+carousel+source[match.start():]).replace('</head>',assets+'</head>',1))
  for i,slug in enumerate(SLUGS):
   body=detail(l,i)
   page=re.sub(r'<main\b.*?</main>',lambda m:body,source,count=1,flags=re.S);assert body in page
   page=re.sub(r'<title>.*?</title>',f'<title>{c["names"][i]} | Imsfrane</title>',page,flags=re.S)
   for lang in D:page=page.replace(f'href="{BASE}{lang}/" lang="{lang}"',f'href="{BASE}{lang}/{slug}/" lang="{lang}"')
   page=re.sub(r'(<a\b[^>]*href=")'+re.escape(BASE)+r'(fr|en|ar|es)/("[^>]*\bhreflang=)',lambda m:m[1]+BASE+m[2]+'/'+slug+'/'+m[3],page)
   page=re.sub(r'(<link\b[^>]*rel="alternate"[^>]*href=")[^"]+/(fr|en|ar|es)/"',lambda m:m[1]+'https://imsfraneinfo.github.io'+BASE+m[2]+'/'+slug+'/"',page)
   page=re.sub(r'(<link\b[^>]*rel="canonical"[^>]*href=")[^"]+',lambda m:m[1]+'https://imsfraneinfo.github.io'+BASE+l+'/'+slug+'/',page)
   page=re.sub(r'(<meta\b[^>]*(?:name="description"|property="og:description"|name="twitter:description")[^>]*content=")[^"]*',lambda m:m[1]+esc(c['descs'][i]),page)
   page=re.sub(r'<script[^>]*type="application/ld\+json"[^>]*>.*?</script>','',page,flags=re.S)
   cfg={k:d[k] for k in ('msg','people','total','each')};cfg.update(lang=l,price=PRICES[i],guide=guide_fee(i),name=c['names'][i],valid=c['valid'])
   page=page.replace('</head>',assets+'</head>',1).replace('</body>','<script type="application/json" id="wo-config">'+json.dumps(cfg,ensure_ascii=False)+'</script></body>',1)
   dest=root/l/slug;dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(page)
  # Preserve old shared links without leaving the obsolete 250 MAD offer online.
  old=root/l/'weekend-vtt';old.mkdir(exist_ok=True)
  (old/'index.html').write_text(f'<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><meta http-equiv="refresh" content="0;url={BASE}{l}/weekend-aventure/"></head><body><a href="{BASE}{l}/weekend-aventure/">{c["names"][1]}</a></body></html>')
 print('Built 5 offers × 4 languages. Per-person prices: '+str(PRICES))
if __name__=='__main__':build()
